package de.corporate.lc.company.service;import de.corporate.lc.company.api.*;import de.corporate.lc.company.domain.CompanyProfile;import de.corporate.lc.company.repository.CompanyProfileRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import java.io.IOException;import java.time.LocalDateTime;import java.util.*;
@Service public class CompanyProfileService{private final CompanyProfileRepository repository;public CompanyProfileService(CompanyProfileRepository r){repository=r;}@Transactional(readOnly=true)public CompanyProfile profile(){return profile(null);}
@Transactional(readOnly=true)public CompanyProfile profile(Integer id){return (id==null?repository.findDefault():repository.findById(id)).orElseThrow(()->new IllegalArgumentException("Firma nicht gefunden."));}
@Transactional(readOnly=true)public List<CompanyProfileView> all(){return repository.findAll().stream().map(CompanyProfileView::from).toList();}
@Transactional public CompanyProfileView create(CompanyProfileRequest r,String username){if(r.legalName()==null||r.legalName().isBlank())throw new IllegalArgumentException("Bitte einen Firmennamen angeben.");CompanyProfile p=new CompanyProfile();p.setId(repository.nextId());repository.save(p);return update(p.getId(),r,username);}@Transactional(readOnly=true)public CompanyProfileView view(){return CompanyProfileView.from(profile());}@Transactional public CompanyProfileView update(CompanyProfileRequest r,String username){return update(null,r,username);}
@Transactional public CompanyProfileView update(Integer id,CompanyProfileRequest r,String username){CompanyProfile p=profile(id);p.setLegalName(clean(r.legalName()));p.setAddressLine(clean(r.addressLine()));p.setPostalCode(clean(r.postalCode()));p.setCity(clean(r.city()));p.setCountry(clean(r.country()));p.setEmail(clean(r.email()));p.setPhone(clean(r.phone()));p.setTaxId(clean(r.taxId()));p.setRegistrationNumber(clean(r.registrationNumber()));p.setBankName(clean(r.bankName()));p.setIban(clean(r.iban()));p.setBic(clean(r.bic()));p.setContactPerson(clean(r.contactPerson()));p.setUpdatedBy(username);p.setUpdatedAt(LocalDateTime.now());return CompanyProfileView.from(repository.save(p));}@Transactional public CompanyProfileView logo(MultipartFile file,String username)throws IOException{return logo(null,file,username);}
@Transactional public CompanyProfileView logo(Integer id,MultipartFile file,String username)throws IOException{if(file.isEmpty()||file.getSize()>2*1024*1024)throw new IllegalArgumentException("Logo fehlt oder ist größer als 2 MB.");String type=Optional.ofNullable(file.getContentType()).orElse("");if(!Set.of("image/png","image/jpeg").contains(type))throw new IllegalArgumentException("Logo muss eine PNG- oder JPEG-Datei sein.");CompanyProfile p=profile(id);p.setLogo(file.getBytes());p.setLogoContentType(type);p.setUpdatedBy(username);p.setUpdatedAt(LocalDateTime.now());return CompanyProfileView.from(repository.save(p));}@Transactional public void deleteLogo(String username){deleteLogo(null,username);}
@Transactional public void deleteLogo(Integer id,String username){CompanyProfile p=profile(id);p.setLogo(null);p.setLogoContentType(null);p.setUpdatedBy(username);p.setUpdatedAt(LocalDateTime.now());}private String clean(String v){return v==null||v.isBlank()?null:v.trim();}}
